      "id": "P1",
      "proposition": "In Tennessee Code Annotated, Section 49-6-3402, every reference to \"grades one through six (1-6)\" is replaced with \"grades one through five (1-5)\".",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "\"grades one through six (1-6)\" wherever it appears in the section and substituting \"grades one\n\nthrough five (1-5)\""
    },
    {
      "id": "P2",
      "proposition": "In Tennessee Code Annotated, Section 49-6-3402, every reference to \"grades seven through twelve (7-12)\" is replaced with \"grades six through twelve (6-12)\".",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "\"grades seven through twelve (7-12)\" wherever it appears in\n\nthe section and substituting \"grades six through twelve (6-12)\"."
    },
    {
      "id": "P3",
      "proposition": "The act takes effect upon becoming a law.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "This act takes effect upon becoming a law, the public welfare requiring it."
    }
  ]
}
